// Note. schema-registry-plugin v2 requires buildscript block
buildscript {
    repositories {
        gradlePluginPortal()
        maven("https://packages.confluent.io/maven/")
    }
}
plugins {
    kotlin("jvm") version "1.9.25"
    kotlin("plugin.spring") version "1.9.25"
    id("org.springframework.boot") version "3.5.7" apply false
    id("io.spring.dependency-management") version "1.1.7"
    id("com.google.protobuf") version "0.9.4" apply false
    id("com.github.davidmc24.gradle.plugin.avro") version "1.9.1" apply false
    id("com.github.imflog.kafka-schema-registry-gradle-plugin") version "2.4.1" apply false
    // ref. https://plugins.gradle.org/plugin/org.jetbrains.kotlin.plugin.serialization
    id("org.jetbrains.kotlin.plugin.serialization") version "2.3.10" apply false
}

group = "com.cowave"
version = "1.0.0"

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

allprojects {
    repositories {
        mavenCentral()
        maven {
            url = uri("https://packages.confluent.io/maven/")
        }
    }
}

fun allSubProjects(action: Action<in Project>) {
    allprojects {
        if (subprojects.isEmpty()) {
            action(this)
        }
    }
}

val coroutineVersion = "1.9.0"
val esClientVersion = "8.13.4"// "9.2.0" //"8.19.6"
val kotestVersion = "5.9.1"

//subprojects {
allSubProjects {

    apply(plugin = "org.jetbrains.kotlin.jvm")
    apply(plugin = "org.jetbrains.kotlin.plugin.spring")
    apply(plugin = "org.springframework.boot")
    apply(plugin = "io.spring.dependency-management")

    dependencyManagement {
        imports {
            mavenBom("org.springframework.boot:spring-boot-dependencies:3.5.7")
            mavenBom("org.springframework.grpc:spring-grpc-dependencies:0.12.0")
        }
        dependencies {
            dependency("org.jetbrains.kotlinx:kotlinx-coroutines-core:$coroutineVersion")
            dependency("org.jetbrains.kotlinx:kotlinx-coroutines-slf4j:$coroutineVersion")
            dependency("org.jetbrains.kotlinx:kotlinx-coroutines-core-jvm:$coroutineVersion")
            dependency("org.jetbrains.kotlinx:kotlinx-coroutines-reactor:$coroutineVersion")

            dependency("io.projectreactor.kotlin:reactor-kotlin-extensions:1.2.4") // 1.2.x latest
            dependency("org.jetbrains.kotlinx:kotlinx-serialization-json:1.10.0")

            dependency("co.elastic.clients:elasticsearch-java:$esClientVersion")
            dependency("org.elasticsearch.client:elasticsearch-rest-client:$esClientVersion")

            dependency("io.kotest:kotest-property-jvm:$kotestVersion")
            dependency("io.kotest:kotest-runner-junit5-jvm:$kotestVersion")
            dependency("io.kotest:kotest-assertions-core-jvm:$kotestVersion")
            dependency("io.kotest.extensions:kotest-extensions-spring:1.1.3")
            dependency("io.kotest.extensions:kotest-extensions-testcontainers:2.0.2")

            dependency("com.google.protobuf:protobuf-kotlin:4.30.2")
            dependency("io.grpc:grpc-kotlin-stub:1.4.3")
            dependency("com.salesforce.servicelibs:reactor-grpc-stub:1.2.4") // TODO 필요한지 확인해볼 것

            dependency("com.fasterxml.jackson.datatype:jackson-datatype-jsr310:2.20.1")
            dependency("io.confluent:kafka-avro-serializer:8.1.1")
            dependency("io.confluent:kafka-json-schema-serializer:8.1.1")

            dependency("com.github.ben-manes.caffeine:caffeine:3.2.3")
        }
    }

    dependencies {
        implementation("org.springframework.boot:spring-boot-starter")
        implementation("org.jetbrains.kotlin:kotlin-reflect")
        implementation("io.github.oshai:kotlin-logging-jvm:7.0.3")

//        testImplementation("org.springframework.boot:spring-boot-starter-test")
//        testImplementation("org.jetbrains.kotlin:kotlin-test-junit5")
//        testRuntimeOnly("org.junit.platform:junit-platform-launcher")
    }

    // Disable Boot JAR for aggregator projects (projects that have child modules)
    plugins.withId("org.springframework.boot") {
        tasks.withType<org.springframework.boot.gradle.tasks.bundling.BootJar>().configureEach {
            enabled = false
        }
    }

    // Set unique jar names based on project path to avoid conflicts
    tasks.withType<Jar>().configureEach {
        val uniqueName = project.path.replace(":", "-").substring(1)
        archiveBaseName.set(uniqueName)
    }

    // 각 모듈의 build 디렉토리 위치를 root의 build 디렉토리로 설정 (모듈마다 build 디렉토리가 따로 생기지 않게 함)
    val safePath = project.path.replace(":", "/").substring(1) // 맨 앞의 '/' 제거
    layout.buildDirectory.set(
        rootProject.layout.buildDirectory.dir(safePath)
//        rootProject.layout.projectDirectory.dir("build/${safePath}")
    )

    kotlin {
        jvmToolchain(21)
    }
}

kotlin {
    compilerOptions {
        freeCompilerArgs.addAll("-Xjsr305=strict")
    }
}

tasks.withType<Test> {
    useJUnitPlatform()
}
